        elif len(args) == 1:
            message = str(args[0])
        else:
            # Join multiple arguments with space, like print()
            message = " ".join(str(arg) for arg in args)
        self.logger.info(message, **kwargs)

    def debug(self, *args, **kwargs):
        """Standard debug log - supports multiple arguments like print()"""
        if len(args) == 0:
            message = ""
        elif len(args) == 1:
            message = str(args[0])
